let page='Inicio',role='Comprador';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const save=()=>localStorage.setItem('sierra-demo',JSON.stringify(data));const money=n=>'$'+Number(n).toFixed(2);const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('es-EC',{day:'numeric',month:'short',year:'numeric'}):'—';const toast=s=>{let el=$('#toast');el.textContent=s;el.style.display='block';setTimeout(()=>el.style.display='none',3000)};
const menus={Comprador:[['⌂','Inicio'],['▦','Catálogo'],['▤','Mis pedidos'],['◉','Precios de referencia']], 'Líder de asociación':[['⌂','Inicio'],['▦','Mis cosechas'],['▤','Pedidos recibidos'],['◉','Precios de referencia']], 'Encargado de precios':[['⌂','Inicio'],['◉','Precios de referencia']],Administrador:[['⌂','Inicio'],['▦','Catálogo'],['▤','Pedidos'],['◉','Precios de referencia'],['♙','Usuarios']]};
function nav(){ $('#nav').innerHTML=menus[role].map(([icon,n])=>`<button class="${page===n?'active':''}" data-page="${n}"><span>${icon}</span>${n}</button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()})}
function title(k,t,s,action=''){return `<div class="eyebrow">${k}</div><div class="page-title"><div><h1>${t}</h1><p class="sub">${s}</p></div>${action}</div>`}
function cards(lots){return lots.length?`<div class="grid">${lots.map(l=>`<article class="product"><div class="product-art product-${({Papa:'papa',Maíz:'maiz',Habas:'habas',Melloco:'melloco',Quinua:'quinua',Cebada:'cebada','Fréjol':'frejol',Zanahoria:'zanahoria',Cebolla:'cebolla',Mora:'mora','Tomate de árbol':'tomate',"Brócoli":"brocoli","Coliflor":"coliflor","Lechuga":"lechuga","Col":"col","Acelga":"acelga","Espinaca":"espinaca","Ajo":"ajo","Apio":"apio","Nabo":"nabo","Remolacha":"remolacha","Zapallo":"zapallo","Sambo":"sambo"})[l.category]||'other'}" role="img" aria-label="Imagen ilustrativa de ${esc(l.category)}"><span class="product-origin">COSECHA DE LA SIERRA</span></div><div class="product-body"><div class="product-top"><div><h3>${esc(l.name)}</h3><p>${esc(l.association)}</p></div><span class="tag">Disponible</span></div><p>⌖ ${esc(l.location)} &nbsp; · &nbsp; ${l.quantity} kg disponibles</p><p>Disponible: ${date(l.date)}</p><div class="product-meta"><div><span class="price">${money(l.price)}</span> <small>/ kg</small></div>${role==='Comprador'?`<button class="btn outline" data-order="${l.id}">Solicitar</button>`:''}</div></div></article>`).join('')}</div>`:'<div class="panel empty">No encontramos cosechas con esos filtros.</div>'}
function home(){let pending=data.orders.filter(o=>o.state==='Pendiente').length;return title('Bienvenido a SierraDirecta','Del campo, más cerca de ti','Una conexión directa entre quienes producen y quienes compran.')+`<section class="hero"><div class="hero-copy"><div class="eyebrow">✦ &nbsp; CULTIVANDO CONEXIONES</div><h2>Lo mejor de nuestra tierra, sin intermediarios.</h2><p>Conecta con productores locales y descubre alimentos frescos que cuentan una historia.</p><button class="btn light" id="explore">${role==='Líder de asociación'?'Ver mis cosechas':'Explorar cosechas'}</button><div class="hero-foot"><span class="hero-avatars">🌱 &nbsp; 🌾 &nbsp; 🧺</span><span>Hecho con orgullo en nuestra Sierra</span></div></div><div class="hero-badge"><span>✳</span><b>Origen local</b><small>De nuestra tierra</small></div></section><div class="stats"><div class="stat"><small>Cosechas publicadas</small><strong>${data.lots.length}</strong><em>Oferta de la comunidad</em></div><div class="stat"><small>Asociaciones</small><strong>${new Set(data.lots.map(l=>l.association)).size}</strong><em>Productores de la Sierra</em></div><div class="stat"><small>Pedidos pendientes</small><strong>${pending}</strong><em>Por gestionar</em></div><div class="stat"><small>Precios de referencia</small><strong>${data.refs.length}</strong><em>Información orientativa</em></div></div><div class="section-head"><div><h2>Cosechas disponibles</h2><p>Productos frescos de nuestras asociaciones</p></div><button class="text-btn" id="all">Ver catálogo</button></div>${cards(data.lots.filter(l=>l.quantity>0).slice(0,3))}`}
function catalog(mine=false){return title('Oferta agrícola',mine?'Mis cosechas':'Explora el catálogo',mine?'Gestiona las cosechas de tu asociación.':'Encuentra productos frescos directamente de las asociaciones.',mine?'<button class="btn" id="newlot">+ Publicar cosecha</button>':'')+`<div class="filters"><input id="search" aria-label="Buscar producto" placeholder="Buscar producto o localidad..."><select id="category" aria-label="Filtrar por categoría"><option value="">Todas las categorías</option><option value="tuberculos">Tubérculos y raíces</option><option value="cereales">Cereales y granos</option><option value="legumbres">Legumbres</option><option value="hortalizas">Hortalizas</option><option value="frutas">Frutas</option></select></div><div id="results"></div>`}
function orders(){return title('Seguimiento',page,'Consulta el estado y la información de cada solicitud.')+`<div class="notice">Los pedidos pendientes no reservan inventario. La disponibilidad se descuenta cuando el líder acepta la solicitud.</div><div class="panel"><table class="table"><thead><tr><th>Pedido</th><th>Producto / asociación</th><th>Cantidad</th><th>Entrega</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${data.orders.length?data.orders.map(o=>`<tr><td><b>#${o.id}</b></td><td><b>${esc(o.name)}</b><br><small>${esc(o.association)}</small></td><td>${o.quantity} kg<br><small>${money(o.quantity*o.price)}</small></td><td>${date(o.date)}<br><small>${esc(o.address)}</small></td><td><span class="status ${o.state==='Aceptado'?'accepted':o.state==='Entregado'?'delivered':o.state==='Rechazado'?'rejected':o.state==='Cancelado'?'cancelled':''}">${esc(o.state)}</span></td><td>${role==='Líder de asociación'&&o.state==='Pendiente'?`<button class="text-btn" data-accept="${o.id}">Aceptar</button><button class="text-btn" data-reject="${o.id}">Rechazar</button>`:role==='Líder de asociación'&&['Aceptado','En preparación'].includes(o.state)?`<button class="text-btn" data-next="${o.id}">Avanzar estado</button>`:role==='Comprador'&&o.state==='Listo para entrega'?`<button class="text-btn" data-next="${o.id}">Confirmar recepción</button>`:role==='Comprador'&&o.state==='Pendiente'?`<button class="text-btn" data-cancel="${o.id}">Cancelar</button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">Todavía no hay pedidos.</td></tr>'}</tbody></table></div>`}
function refs(){return title('Información de mercado','Precios de referencia','Valores orientativos, independientes del precio de cada cosecha.',role==='Encargado de precios'?'<button class="btn" id="newref">+ Agregar referencia</button>':'')+`<div class="notice">Las referencias son datos de demostración. Verifica la fuente y la fecha antes de tomar una decisión.</div><div class="panel"><table class="table"><thead><tr><th>Producto</th><th>Mercado</th><th>Rango USD/kg</th><th>Fuente</th><th>Fecha</th></tr></thead><tbody>${data.refs.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.market)}</td><td>${money(r.min)} – ${money(r.max)}</td><td>${esc(r.source)}</td><td>${date(r.date)}${(Date.now()-new Date(r.date+'T12:00:00').getTime())/86400000>7?' · Desactualizada':''}</td></tr>`).join('')}</tbody></table></div>`}
function users(){return title('Administración','Usuarios de demostración','Ejemplo de los perfiles previstos para la plataforma.')+`<div class="panel"><table class="table"><thead><tr><th>Perfil</th><th>Responsabilidad</th><th>Estado</th></tr></thead><tbody><tr><td>Administrador</td><td>Gestiona la plataforma</td><td>Activo</td></tr><tr><td>Líder de asociación</td><td>Publica y gestiona pedidos</td><td>Activo</td></tr><tr><td>Comprador</td><td>Consulta y solicita cosechas</td><td>Activo</td></tr><tr><td>Encargado de precios</td><td>Registra referencias</td><td>Activo</td></tr></tbody></table></div>`}
function modal(html){$('#modalbody').innerHTML=html;$('#modal').showModal();$('#close').onclick=()=>$('#modal').close()}
function localToday(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function orderForm(id){let l=data.lots.find(x=>x.id===id);modal(`<h2>Solicitar cosecha</h2><p>${esc(l.name)} · ${esc(l.association)} · ${money(l.price)} por kg</p><form id="form"><div class="form-grid"><label>Cantidad (kg)<input name="quantity" type="number" min="1" max="${l.quantity}" required></label><label>Fecha de entrega<input name="date" type="date" min="${localToday()}" required></label><label class="wide">Dirección de entrega<input name="address" required placeholder="Ciudad y dirección"></label></div><div class="modal-actions"><button class="btn outline" type="button" id="close">Cerrar</button><button class="btn">Enviar solicitud</button></div></form>`);$('#form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);if(f.get('date')<localToday()){toast('Selecciona una fecha de hoy o posterior');return}data.orders.unshift({id:Math.max(1000,...data.orders.map(o=>o.id))+1,lotId:l.id,name:l.name,association:l.association,quantity:Number(f.get('quantity')),price:l.price,date:f.get('date'),address:f.get('address'),state:'Pendiente'});save();$('#modal').close();page='Mis pedidos';render();toast('Solicitud creada correctamente') }}
function lotForm(){modal(`<h2>Publicar cosecha</h2><p>Agrega una cosecha de demostración a tu asociación.</p><form id="form"><div class="form-grid"><label>Producto<select name="category"><option>Papa</option><option>Maíz</option><option>Habas</option><option>Melloco</option><option>Quinua</option><option>Cebada</option><option>Fréjol</option><option>Zanahoria</option><option>Cebolla</option><option>Mora</option><option>Tomate de árbol</option><option>Brócoli</option><option>Coliflor</option><option>Lechuga</option><option>Col</option><option>Acelga</option><option>Espinaca</option><option>Ajo</option><option>Apio</option><option>Nabo</option><option>Remolacha</option><option>Zapallo</option><option>Sambo</option></select></label><label>Variedad<input name="variety" required></label><label>Productor<input name="producer" required></label><label>Localidad<input name="location" required></label><label>Cantidad (kg)<input type="number" name="quantity" min="1" required></label><label>Precio (USD/kg)<input type="number" name="price" min="0.01" step="0.01" required></label><label>Fecha disponible<input type="date" name="date" required></label></div><div class="modal-actions"><button class="btn outline" type="button" id="close">Cerrar</button><button class="btn">Publicar</button></div></form>`);$('#form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));data.lots.unshift({...f,id:Date.now(),name:f.category+' '+f.variety,association:'Asociación Tierra Fértil',quantity:Number(f.quantity),price:Number(f.price),icon:({Papa:'🥔',Maíz:'🌽',Habas:'🫛',Melloco:'🌱'})[f.category]});save();$('#modal').close();render();toast('Cosecha publicada') }}
function refForm(){modal(`<h2>Nueva referencia</h2><p>Registra el rango y su fuente en dólares por kilogramo.</p><form id="form"><div class="form-grid"><label>Producto<input name="name" required></label><label>Mercado<input name="market" required></label><label>Precio mínimo<input name="min" type="number" min="0.01" step="0.01" required></label><label>Precio máximo<input name="max" type="number" min="0.01" step="0.01" required></label><label>Fuente<input name="source" required></label><label>Fecha<input name="date" type="date" required></label></div><div class="modal-actions"><button class="btn outline" type="button" id="close">Cerrar</button><button class="btn">Guardar</button></div></form>`);$('#form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(+f.min>+f.max){toast('El mínimo no puede superar al máximo');return}data.refs.unshift(f);save();$('#modal').close();render();toast('Referencia guardada')}}
const gruposCatalogo={tuberculos:['Papa','Melloco','Zanahoria','Nabo','Remolacha'],cereales:['Maíz','Quinua','Cebada'],legumbres:['Habas','Fréjol'],hortalizas:['Cebolla','Brócoli','Coliflor','Lechuga','Col','Acelga','Espinaca','Ajo','Apio','Zapallo','Sambo'],frutas:['Mora','Tomate de árbol']};
function render(){nav();const content=$('#content');content.classList.remove('view-enter');void content.offsetWidth;content.classList.add('view-enter');$('#content').innerHTML=page==='Inicio'?home():['Catálogo','Mis cosechas'].includes(page)?catalog(page==='Mis cosechas'):['Mis pedidos','Pedidos recibidos','Pedidos'].includes(page)?orders():page==='Usuarios'?users():refs();document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>orderForm(+b.dataset.order));if($('#explore'))$('#explore').onclick=()=>{page=role==='Líder de asociación'?'Mis cosechas':'Catálogo';render()};if($('#all'))$('#all').onclick=()=>{page=role==='Líder de asociación'?'Mis cosechas':'Catálogo';render()};if($('#newlot'))$('#newlot').onclick=lotForm;if($('#newref'))$('#newref').onclick=refForm;if($('#search')){let filter=()=>{$('#results').innerHTML=cards(data.lots.filter(l=>l.quantity>0&&(page!=='Mis cosechas'||l.association==='Asociación Tierra Fértil')&&(!$('#category').value||(gruposCatalogo[$('#category').value]||[]).includes(l.category))&&[l.name,l.location,l.association].some(x=>x.toLowerCase().includes($('#search').value.toLowerCase()))));document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>orderForm(+b.dataset.order))};$('#search').oninput=filter;$('#category').onchange=filter;filter()}document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>{let o=data.orders.find(x=>x.id===+b.dataset.accept),l=data.lots.find(x=>x.id===o.lotId);if(!l||l.quantity<o.quantity){toast('Stock insuficiente. El pedido sigue pendiente.');return}l.quantity-=o.quantity;o.state='Aceptado';save();render();toast('Pedido aceptado y stock actualizado')});document.querySelectorAll('[data-reject],[data-cancel]').forEach(b=>b.onclick=()=>{let id=+(b.dataset.reject||b.dataset.cancel),o=data.orders.find(x=>x.id===id);o.state=b.dataset.reject?'Rechazado':'Cancelado';save();render();toast('Estado actualizado')});document.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>{let o=data.orders.find(x=>x.id===+b.dataset.next);o.state=({'Aceptado':'En preparación','En preparación':'Listo para entrega','Listo para entrega':'Entregado'})[o.state];save();render();toast('Estado actualizado')})}
$('#role').onchange=e=>{role=e.target.value;page='Inicio';render()};render();
